// The constant-pattern shuffle forms must match the generic shuffle for
// every pattern in the corpus, after the emitter's normalization.
func TestGoSIMDShuffleConst(t *testing.T) {
	for _, pat := range simdGCorpus {
		var ia, ib [2]uint64
		singleA, singleB := true, true
		for i := 0; i < 16; i++ {
			idx := uint8(pat[i>>3] >> (8 * uint(i&7)))
			va, vb := uint8(0x80), uint8(0x80)
			if idx < 16 {
				va = idx
				singleB = false
			} else if idx < 32 {
				vb = idx - 16
				singleA = false
			}
			ia[i>>3] |= uint64(va) << (8 * uint(i&7))
			ib[i>>3] |= uint64(vb) << (8 * uint(i&7))
		}
		for _, a := range simdGCorpus[:20] {
			for _, b := range simdGCorpus[:20] {
				want := simd_i8x16_shuffle(a, b, pat)
				if got := simd_g_to(simd_g_i8x16_shuffle2(simd_g_from(a), simd_g_from(b), simd_g_from(ia), simd_g_from(ib))); got != want {
					t.Fatalf("shuffle2(%#x, %#x, pat %#x) = %#x, want %#x", a, b, pat, got, want)
				}
				if singleA {
					if got := simd_g_to(simd_g_i8x16_swizzle_c(simd_g_from(a), simd_g_from(ia))); got != want {
						t.Fatalf("swizzle_c(a) pat %#x = %#x, want %#x", pat, got, want)
					}
				}
				if singleB {
					if got := simd_g_to(simd_g_i8x16_swizzle_c(simd_g_from(b), simd_g_from(ib))); got != want {
						t.Fatalf("swizzle_c(b) pat %#x = %#x, want %#x", pat, got, want)
					}
				}
			}
		}
	}
}

