// simdGTrap runs f and reports whether it trapped (panicked).
func simdGTrap(f func()) (trapped bool) {
	defer func() {
		if recover() != nil {
			trapped = true
		}
	}()
	f()
	return false
}

var nan32 = math.Float32frombits(0x7fc00000)
var nan64 = math.Float64frombits(0x7ff8000000000000)
